       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@anionex/dsh-vision-toolkit','dsh-vision-toolkit','Anionex','https://github.com/Anionex/dsh-vision-toolkit',NULL,'vision','Vision for text-only models: paste an image and the model switches to a Vision Toolkit variant for image Q&A, multi-image comparison, long-screenshot OCR, screenshot-to-UI reproduction, element grounding, and pixel diff. No API key by default — images are processed by the author-hosted free service, 100 per machine per day; configurable to your own provider.','让纯文本模型处理视觉任务：粘贴图片后自动切换到 Vision Toolkit 变体，支持图片问答、多图比较、长截图 OCR、截图还原前端 UI、元素定位与像素对比。默认无需 API Key——图片经作者自建的免费服务处理，每台机器每天 100 张；也可改为指向自己的服务商。','@anionex/dsh-vision-toolkit',NULL,'dsh plugin --profile web add @anionex/dsh-vision-toolkit','npm',883,23549,906549,'0.1.45','2026-08-13','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'56b8b7bb')
