INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:sutera-diffusus/dsh-whale-musume','dsh-whale-musume','Sutera-Diffusus','https://github.com/Sutera-Diffusus/dsh-whale-musume',NULL,'fun','A whale-girl desktop pet for the DeepSeek Harness Web UI: pat-to-raise growth, work-state poses per tool type, 494 dialogue lines, 30 achievements, a growth diary, drag physics, theme sync and an accessibility mode. Chat-keyword sensing and API-balance care ship off and are opt-in; an optional weather mood calls Open-Meteo only after you name a city. No telemetry.','元气鲸鱼娘桌宠：摸头养成、按工具类型联动的工作状态、494 条台词、30 项成就、成长日记、拖拽惯性、主题适配与无障碍模式。关键词感知与余额关心默认关闭、需手动开启；可选的天气心情只在你填了城市后才会请求 Open-Meteo。无遥测。',NULL,NULL,'dsh plugin --profile web add github:Sutera-Diffusus/dsh-whale-musume','github',74,0,74000,'','2026-08-18','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'39770a9d')
