INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@wingsky-1/dsh-mcp-manager','dsh-plugin-hub#packages/dsh-mcp-manager','wingsky-1','https://github.com/wingsky-1/dsh-plugin-hub/tree/main/packages/dsh-mcp-manager',NULL,'tools','MCP server manager (stdio / streamable-http): per-working-directory project and global config tiers; project-level MCP collapsed into 4 atomic tools through a middleware layer by default (`middleware: all` folds in global servers too, hot-switchable in the settings page); workspace isolation prevents cross-project interference; configs keep `${ENV}` references only, with no plaintext secrets on disk; runtime registration API for other plugins to inject MCP servers.','MCP 服务器管理器（stdio / streamable-http）：按工作目录分项目级/全局两级配置；项目级 MCP 默认经中间层收敛为 4 个原子工具（`middleware: all` 连同全局服务器一并收敛，设置页热切换）；工作空间隔离防串台；配置只存 `${ENV}` 引用、不落盘明文密钥；提供运行时注册接口供其他插件注入 MCP。','@wingsky-1/dsh-mcp-manager',NULL,'dsh plugin --profile web add @wingsky-1/dsh-mcp-manager','npm',19,4092,23092,'0.2.5','2026-08-18','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'54a70e77')
     ON CONFLICT(id) DO UPDATE SET stars=excluded.stars, downloads=excluded.downloads, score=excluded.score,
