INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-voice-mode','dsh-voice-mode#dsh-voice-mode','qishuilalala','https://github.com/qishuilalala/dsh-voice-mode/tree/main/plugin/dsh-voice-mode',NULL,'voice','Full-duplex voice mode for the DeepSeek Harness Web UI: toggle (2s-pause auto-send) or hold-to-talk dictation into an editable draft with zipformer2 streaming ASR, optional wake word; sentence-by-sentence Edge TTS read-aloud with live captions, and speaking interrupts playback and the running turn (true barge-in). On-device ASR, no API key.','DeepSeek Harness Web UI 全双工语音对话：按钮或 Ctrl+Shift+V 进入，持续聆听（停顿自动发送）或按住说话，zipformer2 流式识别入可编辑草稿、可选唤醒词；回复按句 Edge TTS 朗读并显示实时字幕，开口即打断播放与回合（真 barge-in）；识别模型本地推理、Edge TTS 在线合成，无需 API Key。','dsh-voice-mode',NULL,'dsh plugin --profile web add dsh-voice-mode','npm',12,5095,17095,'0.7.14','2026-08-24','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'a89e6c6a')
