INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@winteries/dsh-turn-fold','dsh-turn-fold','Winter-And-You-Gone','https://github.com/Winter-And-You-Gone/dsh-turn-fold',NULL,'ui','A better fold bar: automatically folds tool calls and Think segments into step fold bars, and collapses each finished turn into a single turn header with live metrics (duration, TTFT, token, tok/s, cache hit) — only the final summary stays visible; customizable leading icons with animated poker cards built in (suit-cycling card animation while running, a deck when collapsed, a fan when expanded), a settings row for the official fold mode, compatible with both new and old DSH versions. Zero intrusion into DSH source.','更好的折叠栏：将工具调用与 Think 段自动折叠为步骤折叠栏，回合结束后整回合收拢为带实时指标（耗时/首字/token/tok/s/缓存命中）的回合折叠栏，只保留最终总结正文；前导图标可自定义，内置动态扑克牌（运行中花色循环卡牌动画、收起牌堆、展开扇形），提供官方折叠方式设置行，适配 DSH 新旧版本。零侵入 DSH 源码。','@winteries/dsh-turn-fold',NULL,'dsh plugin --profile web add @winteries/dsh-turn-fold','npm',12,465,12465,'0.5.3','2026-08-18','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'f6f7f5d9')
