       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:ywleeo/browser-mcp','browser-mcp','ywleeo','https://github.com/ywleeo/browser-mcp',NULL,'browser','Drives a real Chrome through a local MCP server so the agent can search Google/Bing/Sogou, read any page including JS-rendered and login-only content, automate click/scroll/type/key-press/select in a background window, and run platform search/detail/comment/download for Zhihu, Xiaohongshu, Douyin, Bilibili, X and Reddit; resumable comments, SHA-256-verified downloads, cookies never returned, localhost only.','通过本地 MCP server 驱动你真实的 Chrome：可搜索 Google/Bing/搜狗、读取任意页面（含 JS 渲染与登录后内容）、在后台窗口自动化点击/滚动/输入/按键/选择，并为知乎、小红书、抖音、Bilibili、X、Reddit 提供平台级搜索/详情/评论/下载；评论断点续抓、下载 SHA-256 校验、不返回 cookie、仅本地回环。',NULL,NULL,'dsh plugin --profile web add github:ywleeo/browser-mcp','github',6,0,6000,'','2026-08-25','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'8739e7a5')
