       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@creait/dsh-tool-disclosure','dsh-plugins#tool-disclosure','CREAIT-nl','https://github.com/CREAIT-nl/dsh-plugins/tree/main/tool-disclosure',NULL,'tools','Progressive tool disclosure: a deferred tool group costs one catalog line instead of its full schemas until the model loads it with tool_search, with one switch per group in Settings and each group measured against the live registry.','渐进式工具披露：被延后的工具组在每次请求中只占目录里的一行，模型用 tool_search 加载后才拿到完整 schema；设置页为每个组提供一个开关，各组开销按当前工具注册表实测。','@creait/dsh-tool-disclosure',NULL,'dsh plugin --profile web add @creait/dsh-tool-disclosure','npm',5,262,5262,'0.1.0','2026-08-24','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'aa2a7f8f')
