INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-github-router','dsh-github-router','AngelosZou','https://github.com/AngelosZou/dsh-github-router',NULL,'dev','Read-only GitHub access for agents, wrapping several tools. Inside the tool it automatically probes and selects whichever GitHub access method works locally, and tries network proxies on its own. That cuts down the network and parsing problems an agent may hit when accessing GitHub, and the overhead of it repeatedly trying different approaches.','面向 agent 的只读 GitHub 访问，封装多个工具。在工具内部自动探测与选择本地可用的 GitHub 访问设施，并自动尝试网络代理。减少 Agent 在访问 GitHub 时可能遇到的网络问题或解析问题，减少 Agent 频繁尝试不同方案的开销。','dsh-github-router',NULL,'dsh plugin --profile web add dsh-github-router','npm',2,738,2738,'0.3.2','2026-09-08','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'a0673251')
