INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-concise','dsh-concise','hoyyang','https://github.com/hoyyang/dsh-concise',NULL,'session','One-click Concise output style for DeepSeek Harness: results first, no filler, same work depth. Every final reply opens with a plain-language digest card (select text to copy), scoped per session, working in headless/CLI too, with /concise command, style.md overrides and a local API. Links and file paths inside the digest card render as clickable chips: URLs jump, local files open with the OS default app (v0.9+).','DeepSeek Harness 一键 Concise 输出风格开关：结果先行、少废话，工作深浅不变。每轮最终回答开头自动附「摘要」精华卡（划选即复制），按会话独立生效，headless/CLI 同样生效，支持 /concise 命令、style.md 自定义风格与本地 API。摘要卡内的链接与文件路径渲染为可点击 chip：网页跳转、本地文件用系统默认应用打开（v0.9+）。','dsh-concise','https://github.com/hoyyang/dsh-concise/releases/download/v0.10.3/dsh-concise-0.10.3.tgz','dsh plugin --profile web add dsh-concise','npm',1,460,1460,'0.10.3','2026-09-18','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'cb9791d4')
