       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-whale-copilot','dsh-whale-copilot','spartaattack','git+https://github.com/Moveharder/dsh_plugins.git',NULL,'notify','DSWhale Copilot — 一条由 DSH 事件驱动的 DeepSeek 蓝色小鲸鱼伙伴：随 agent 会话的思考/回复/工具执行/审批/提问/完成等事件游泳、起伏、跳跃、间歇喷水，游动模式下还会时不时探出水面连喷几次水；支持游动/静态（可拖拽摆放）两种模式，海洋背景高度随鲸鱼大小与气泡位置自适应且可一键隐藏，审批与提问时暂停移动并抖动提醒（可开启全浏览器醒目提醒），并带跟随鲸鱼位置的会话状态面板（支持深/浅主题）。A cute whale copilot for the DSH Web sur','个人维护的 DSH 插件大合集，各插件独立更新发布，帮你一站式查找、安装和扩展实用功能。','dsh-whale-copilot',NULL,'dsh plugin --profile web add dsh-whale-copilot','npm',0,1452,1452,'1.3.3','2026-09-10','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'83769eb2')
