       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-whale-particles','dsh-whale-particles','fewoot','https://github.com/fewoot/dsh-whale-particles',NULL,'ui','Dot-matrix backdrop for the DSH Web UI: the dots form the DeepSeek whale or a transparent PNG you import (alpha-masked), each dot carries its own low-frequency force and follows the cursor in manual mode, while an auto screensaver mode sweeps 360-degree waves and full-screen breathing across the artwork; sliders and toggles live under Settings > Plugins.','给 DSH Web 加一层点阵背景:点阵可组成鲸鱼剪影,或导入透明 PNG 按 alpha 取主体;每颗粒子各自持有低频外力,手动模式下跟随光标扰动,自动屏保模式则用 360° 任意方向的扫波与全屏呼吸带动整幅图案;鼠标/自动与鲸鱼/照片在参数面板里切换,入口在 设置 → 插件。','dsh-whale-particles','https://github.com/fewoot/dsh-whale-particles/releases/download/v0.3.0/dsh-whale-particles-0.3.0.tgz','dsh plugin --profile web add dsh-whale-particles','npm',0,196,196,'0.3.0','2026-09-06','2026-09-20T04:53:29.876Z','2026-09-20T04:53:29.876Z',0,NULL,'638a3aba')
